changeSet.sql:
CREATE TABLE question_sources ( id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), question_id UUID NOT NULL REFERENCES questions(id) ON DELETE CASCADE, source_id UUID NOT NULL REFERENCES sources(id) ON DELETE CASCADE, quote TEXT, context TEXT, location TEXT, page_id UUID REFERENCES lib_pages(id) ON DELETE RESTRICT, range_start INTEGER, range_end INTEGER, pdf_file_id UUID REFERENCES library_files(file_id) ON DELETE RESTRICT, pdf_page_number INTEGER, pdf_bbox JSONB, image_region_id UUID REFERENCES lib_image_regions(id) ON DELETE RESTRICT, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
ALTER TABLE question_sources ADD CONSTRAINT chk_question_sources_one_mode CHECK ( (page_id IS NOT NULL AND range_start IS NOT NULL AND range_end IS NOT NULL AND range_start >= 0 AND range_end > range_start AND pdf_file_id IS NULL AND image_region_id IS NULL) OR (pdf_file_id IS NOT NULL AND pdf_page_number IS NOT NULL AND pdf_bbox IS NOT NULL AND pdf_page_number >= 1 AND page_id IS NULL AND image_region_id IS NULL) OR (image_region_id IS NOT NULL AND page_id IS NULL AND pdf_file_id IS NULL) OR (page_id IS NULL AND pdf_file_id IS NULL AND image_region_id IS NULL) );
CREATE INDEX idx_question_sources_question_id ON question_sources(question_id); CREATE INDEX idx_question_sources_source_id ON question_sources(source_id); CREATE INDEX idx_question_sources_page_id ON question_sources(page_id) WHERE page_id IS NOT NULL; CREATE INDEX idx_question_sources_pdf_file_id ON question_sources(pdf_file_id) WHERE pdf_file_id IS NOT NULL; CREATE INDEX idx_question_sources_image_region_id ON question_sources(image_region_id) WHERE image_region_id IS NOT NULL;

rollback.sql:
DROP INDEX IF EXISTS idx_question_sources_image_region_id;
DROP INDEX IF EXISTS idx_question_sources_pdf_file_id;
DROP INDEX IF EXISTS idx_question_sources_page_id;
DROP INDEX IF EXISTS idx_question_sources_source_id;
DROP INDEX IF EXISTS idx_question_sources_question_id;
DROP TABLE question_sources;
